INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'adjust.note', 'fr', 'Les modifications ne valent que sur cette page &mdash; rien n''est enregistré, et un rechargement rétablit le calendrier calculé à rebours. Un pays que vous déplacez au-delà de sa propre échéance reste visible et est signalé plus haut, car un plan qui manque une date est une décision et non une erreur.');
