INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.durations', 'fr', 'Les durées s''entendent par pays. Les pays partageant une date de mise en service forment une vague : une vague de cinq pays coûte donc environ cinq chantiers-pays d''effort, répartis sur autant de chantiers que vous pouvez réellement mener de front.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.grades', 'fr', 'Chaque chiffre indique son origine. <span class="tag tA">A</span> mesuré et primaire &middot; <span class="tag tB">B</span> organisme crédible, sans source &middot; <span class="tag tD">D</span> notre estimation. Une valeur que vous saisissez l''emporte toujours sur notre valeur par défaut &mdash; ce panneau est là pour ça.');
