INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'assumptions.placeholders', 'fr', 'Ces chiffres sont <strong>de simples valeurs indicatives</strong>. Merci de les remplacer par des estimations budgétaires de votre prestataire et de considérer le ROI comme illustratif, tant que des données réelles ne sont pas disponibles.');
