INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.ap.just2', 'fr', ' Seules la saisie et la validation sont portées au crédit de la conformité &mdash; 9 des 21 minutes de traitement AP {0} &mdash; parce que la revue et l''approbation sont des décisions de gestion qu''aucun format de facture ne supprime.');
