INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.arShare2.just', 'fr', 'Coût d''émission issu des chiffres de canal de l''ATO {0} sur sa propre répartition 60/40 {1}. Fourchette de réduction {2}. La part d''émission structurée est la vôtre, et notre valeur par défaut est délibérément la mesure la plus élevée dont nous disposons {3}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.cycle2.just', 'fr', 'Les relances fournisseurs occupent <strong>12,8 %</strong> du temps des équipes AP contre <strong>24,0 %</strong> {0} ; délai de traitement <strong>2,9 jours</strong> contre <strong>13,5</strong> {1} ; <strong>15 % de relances en moins</strong> dans un trust {2}. Des corrélations avec une fonction AP performante, pas des effets mesurés.');
