INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'basis.penalty.just', 'fr', '{0} de vos pays publient un barème de pénalités chiffré {1}. Dimensionnez cela pays par pays ; il n''existe aucun agrégat crédible.');
