INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA', 'fr', 'Note A');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA.body', 'fr', 'Ardent Partners 2025 (coût, délai de traitement, taux d''exception et de relance fournisseur) &middot; ATO / Deloitte Access Economics (papier contre PDF contre e-facture, données de 2016, indiqué) &middot; OCDE DCTR 2026 (mécanisme) &middot; les données de suivi propres à ce site.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeA.tag', 'fr', 'mesuré &amp; primaire');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB', 'fr', 'Note B');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB.body', 'fr', 'HMRC/DBT : réduction de coût de 60&ndash;80 % et taux d''erreur manuel d''environ 10 %. Les deux figurent dans une consultation du gouvernement britannique, aucun avec une source à l''intérieur. Utilisés ici, cette lacune étant consignée.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeB.tag', 'fr', 'organisme crédible, sans source');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC', 'fr', 'Note C');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC.body', 'fr', 'Les chiffres du NHS trust (24 h contre 10 jours, paiement deux fois plus rapide, 15 % de relances en moins) proviennent d''une seule organisation non nommée et non datée. Les chiffres sur l''écart de TVA viennent de la Commission européenne et de CASE, non de l''OCDE, et les analyses pays de la Commission elle-même attribuent l''évolution à la reprise économique plutôt qu''à la télédéclaration.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeC.tag', 'fr', 'anecdote, pas une référence');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD', 'fr', 'Note D');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD.body', 'fr', 'Le temps de résolution par facture erronée, les coûts chargés par ETP, la part de l''effort fiscal. Ce sont nos estimations de départ, affichées pour que vous puissiez les remplacer par les vôtres.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeD.tag', 'fr', 'votre hypothèse');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.gradeLabel', 'fr', 'Niveau de preuve {0}');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.hmrcAto', 'fr', 'HMRC, corroboré par l''ATO');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.hmrcRate', 'fr', 'Consultation HMRC');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.nhsQuery', 'fr', '15 % de relances en moins');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.oecdDctr', 'fr', 'OCDE DCTR, 2026');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.ourAssumption', 'fr', 'notre hypothèse');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.site.body', 'fr', 'Les données d''obligation viennent du suivi propre à ce site : statut, modèle et échéances datées par pays, chacun traçable jusqu''au texte juridique cité sur la fiche détaillée du pays &mdash; c''est là la garantie, et non une affirmation sur la fraîcheur de la vérification.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.siteLabel', 'fr', 'Source : données de suivi');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.sourceLink', 'fr', 'source');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.taskSplit', 'fr', 'la répartition des tâches');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.trackerDates', 'fr', 'dates du suivi');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.treasury', 'fr', 'Utilisez votre propre taux de trésorerie pour tout ce que vous signerez');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.whyNot', 'fr', 'pourquoi non');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.whyNotAll', 'fr', 'pourquoi pas tous');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourCall', 'fr', 'à vous de juger');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourMins', 'fr', 'votre temps de résolution');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yourShare', 'fr', 'votre chiffre');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'ev.yours.body', 'fr', 'Votre hypothèse. Rien n''est affirmé pour ce chiffre &mdash; il est exposé pour qu''on puisse discuter le modèle plutôt que le croire.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'footer.pdf', 'fr', 'Cet outil modélise un dossier de rentabilité ; ce n''est pas un conseil fiscal, juridique ou d''investissement. Les chiffres notés D sont nos estimations de départ et non des références &mdash; remplacez-les par les vôtres avant qu''une décision ne repose dessus.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'footer.text', 'fr', '<strong>The E-Invoicing Compliance Corner</strong> &mdash; planificateur ROI &amp; vagues. Chaque date d''obligation ici est traçable jusqu''au texte juridique cité sur la fiche détaillée du pays, et c''est là qu''il faut la vérifier. Les chiffres de référence portent le niveau de preuve indiqué en regard de chacun. Cet outil modélise un dossier de rentabilité ; ce n''est pas un conseil fiscal, juridique ou d''investissement.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'fx.converted', 'fr', 'Converti à un <strong>taux fixe</strong> de 1 {0} = {1} USD &mdash; non actualisé quotidiennement.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'fx.convertedDated', 'fr', 'Converti à un <strong>taux fixe</strong> de 1 {0} = {1} USD, cours au comptant {2} &mdash; non actualisé quotidiennement.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.body2', 'fr', 'Vos chiffres sont ci-dessus et ils sont à vous. Un compte gratuit enregistre les pays que vous avez sélectionnés, vous prévient par e-mail lorsqu''une de ces obligations évolue réellement, et retient vos hypothèses pour la prochaine fois. Il suffit d''un code à 6 chiffres, sans mot de passe &mdash; et vous restez sur cette page.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.cta2', 'fr', 'Créer un compte gratuit');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.eyebrow', 'fr', 'Compte gratuit');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.signin', 'fr', 'Vous en avez déjà un ? {0}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.signin.link', 'fr', 'Se connecter');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'gate.title', 'fr', 'Gardez ceci, et soyez averti des changements');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'grp.named', 'fr', 'Nommé, non chiffré &mdash; réel, mais ce modèle n''inventera pas de montant pour cela');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'grp.priced', 'fr', 'Chiffré &mdash; comptabilisé dans le dossier de rentabilité');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.capture', 'fr', '<strong>L''effectif de saisie vaut plus que l''ensemble de l''économie de traitement.</strong> {0} de coût de saisie libéré face à {1} de réduction totale du traitement AP. Ce sont deux chemins vers le même argent, le premier ne peut donc pas dépasser le second &mdash; vérifiez le taux de saisie de données et le coût AP par facture, car l''un des deux est faux.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.excGap', 'fr', '<strong>Ce modèle supprime plus d''exceptions que ce qui sépare le meilleur quartile des fonctions AP de toutes les autres.</strong> Votre taux d''erreur et votre hypothèse d''élimination retirent ensemble {0} points de factures du circuit d''exception ; Ardent mesure l''écart complet entre Best-in-Class et tous les autres à {1} points {2}, toutes causes confondues et avec la facturation électronique comme un facteur parmi d''autres. Baissez le taux d''erreur ou le pourcentage d''élimination &mdash; en l''état, la ligne des reprises revendique plus que ce qu''atteignent les meilleurs acteurs du marché.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.heading', 'fr', '{0} {1} à vérifier avant d''utiliser ces chiffres');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.late.one', 'fr', '<strong>{0} date de début fixée se termine après l''échéance.</strong> {1}. Cela peut être délibéré &mdash; un retard assumé est une décision qu''un comité peut prendre &mdash; mais le plan ci-dessous ne respecte plus cette date.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.late.other', 'fr', '<strong>{0} dates de début fixées se terminent après l''échéance.</strong> {1}. Cela peut être délibéré &mdash; un retard assumé est une décision qu''un comité peut prendre &mdash; mais le plan ci-dessous ne respecte plus ces dates.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.disc', 'fr', '{0} &mdash; {1} (planifié comme discrétionnaire)');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.one', 'fr', '<strong>{0} pays sélectionné a une obligation antérieure à la date pour laquelle ce plan prévoit.</strong> {1}. Ce sont des obligations datées et en vigueur que le suivi public de ce site n''affiche pas, le plan de vagues ne les programme donc pas. La marge affichée pour lui est plus longue que celle dont il dispose réellement.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.other', 'fr', '<strong>{0} pays sélectionnés ont des obligations antérieures à la date pour laquelle ce plan prévoit.</strong> {1}. Ce sont des obligations datées et en vigueur que le suivi public de ce site n''affiche pas, le plan de vagues ne les programme donc pas. La marge affichée pour eux est plus longue que celle dont ils disposent réellement.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.mistimed.planned', 'fr', '{0} &mdash; {1} (prévu pour {2})');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.payback', 'fr', '<strong>Récupération en moins d''un mois.</strong> Aucun programme de facturation électronique ne se rentabilise aussi vite. Vérifiez les volumes et les coûts par facture &mdash; l''un des deux est faux d''un ordre de grandeur, et tout le reste de cette page en hérite.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.selectFirst', 'fr', '<strong>Sélectionnez d''abord au moins un pays.</strong> Le plan de vagues, le nombre d''intégrations et tout le volet investissement se construisent à partir des pays dans lesquels vous facturez &mdash; sans sélection, il n''y a aucun programme à chiffrer.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.soon', 'fr', '<strong>{0} doit commencer sous 90 jours</strong> pour tenir l''échéance publiée avec vos hypothèses de phase actuelles.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.taxCap', 'fr', '<strong>L''économie sur l''effort fiscal est plafonnée, et le plafond mord.</strong> {0} impliquerait {1} % de votre effort AP ; le modèle n''en retient pas plus de {2} %, parce que l''ordre de grandeur est notre hypothèse et non une référence, et qu''un plafond absent partirait à la dérive. Ajouter d''autres pays ne bougera pas le chiffre indirect &mdash; mais continuera d''ajouter du coût, et c''est là l''asymétrie honnête.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.zeroInt.one', 'fr', '<strong>{0} pays sélectionné a une obligation, mais le modèle a chiffré zéro intégration.</strong> Ce n''est pas un programme bon marché, c''est un calcul cassé &mdash; considérez chaque chiffre ci-dessous comme non fiable tant que ce n''est pas expliqué.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'guard.zeroInt.other', 'fr', '<strong>{0} pays sélectionnés ont une obligation, mais le modèle a chiffré zéro intégration.</strong> Ce n''est pas un programme bon marché, c''est un calcul cassé &mdash; considérez chaque chiffre ci-dessous comme non fiable tant que ce n''est pas expliqué.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.arShare', 'fr', 'La part des factures que vous ÉMETTEZ qui partent déjà sous forme d''e-factures structurées — pas des PDF par e-mail, que le destinataire doit encore lire et saisir. Une économie ne se prend qu''une fois : ce qui part déjà structuré l''a déjà prise. Valeur par défaut 64 % : Billentis situe l''Europe à ce niveau et le monde à 29 %.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cImplC', 'fr', 'Coût unique pour raccorder un système de facturation à un pays COMPLEXE — clearance ou déclaration, donc certification, gestion des erreurs et rapprochement des statuts. Une valeur indicative, comme ci-dessus. Remplacez-la par votre devis.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cImplS', 'fr', 'Coût unique pour raccorder un système de facturation à un pays SIMPLE — un échange 4 coins, sans l''administration fiscale dans la boucle. Une valeur indicative : aucun cabinet d''analystes ne publie de chiffre crédible par pays. Remplacez-la par votre devis.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cPlat', 'fr', 'Frais annuels de plateforme, de réseau ou de point d''accès pour l''ensemble des pays du périmètre. Calculés à partir d''un tarif par document appliqué à vos volumes AP et AR réunis. Une valeur indicative — les prix des prestataires varient d''un ordre de grandeur. Une valeur que vous saisissez cesse de suivre les volumes.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cRun', 'fr', 'Vos propres coûts annuels pour exploiter le service une fois en production : supervision, gestion des exceptions et suivi des évolutions réglementaires. Une valeur indicative, et souvent sous-estimée — le travail sur les obligations ne s''arrête jamais.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.colBanks', 'fr', 'Si une économie arrive avec la construction de conformité elle-même, ou si elle exige un programme de transformation AP plus large que vous ne menez peut-être pas. Les factures structurées se comptabilisent et se soldent sans lui ; une refonte des processus non. Chaque ligne indique lequel, et pourquoi, dans sa justification.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.complexity', 'fr', 'COMPLEXE lorsque l''administration fiscale voit les données au niveau de la facture : clearance, modèle 5 coins ou télédéclaration. SIMPLE sinon. Attribué à la main pays par pays dans le suivi, pas déduit d''un texte. Détermine à la fois le tarif d''intégration et les durées de phase.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.costAR', 'fr', 'Coût d''émission d''une facture client aujourd''hui. Inférieur au chiffre AP parce que l''émission n''a ni rapprochement ni approbation. Calculé à partir des coûts de canal ATO / Deloitte en utilisant la répartition 60/40 de l''ATO elle-même (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.costNow', 'fr', 'Coût complet de traitement d''une facture fournisseur aujourd''hui — personnes, systèmes, exceptions, approbations, pas seulement les licences. Constitue la base à laquelle la réduction s''applique. Moyenne de marché Ardent Partners, données 2025 (note A).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.countries', 'fr', 'Données d''obligation à jour issues du suivi propre à ce site — statut, modèle et échéance datée par pays, chacun traçable jusqu''au texte juridique cité sur la fiche détaillée du pays. La donnée d''entrée qui change le plus le résultat.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.cur', 'fr', 'Convertit chaque montant de la page, y compris les valeurs de référence par défaut et toute valeur que vous avez remplacée. Le taux est un cours au comptant relevé à la date indiquée puis stocké, non actualisé quotidiennement, afin que le même scénario donne la même réponse des mois plus tard. Utilisez votre propre taux de trésorerie pour tout ce que vous signerez.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.eShare', 'fr', 'La part de vos factures fournisseurs qui arrivent déjà sous forme d''e-factures structurées — pas des PDF, qu''il faut encore lire et saisir. Une économie ne se prend qu''une fois : c''est donc le principal levier sur la ligne AP. Ardent situe le marché à 51 % (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.erp', 'fr', 'Systèmes ERP ou de facturation distincts devant émettre ou recevoir des factures — pas des entités juridiques ; les entités partageant un système comptent pour une. Chaque système après le premier ajoute 12 % à la conception et à la construction, plafonné à +60 %.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errElim', 'fr', 'Quelle part des factures aujourd''hui erronées la facturation électronique supprime réellement. Valeur par défaut 80 % plutôt que 100 %, parce qu''un litige ou une livraison incomplète bloque une facture quel que soit le format d''arrivée. Notre hypothèse (note D).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errMins', 'fr', 'Temps de travail effectif pour régler une facture arrivée avec de mauvaises données : relancer le fournisseur, ressaisir, faire réapprouver. Valorisé au taux de saisie de données ci-dessous. ATO : 15 minutes pour une exception de traitement, 5 pour une simple correction de saisie (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.errRate', 'fr', 'Part des factures traitées manuellement comportant une erreur qui exige une reprise. Dimensionne la ligne des reprises. Consultation HMRC / DBT, 2025, qui affirme 10 % sans citer aucune étude (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.fteCost', 'fr', 'Coût annuel complet d''un ETP fiscal ou finance. Ne dimensionne que l''économie indirecte sur l''effort fiscal, et il est plafonné. Délibérément différent du taux de saisie voisin — environ le double, et rarement délocalisé. Salaire BLS chargé du facteur de coût employeur BLS (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.fteEntry', 'fr', 'Coût annuel complet du poste de saisie ou de courrier qui réceptionne les factures fournisseurs. Exprime l''économie de traitement en effectifs ; il n''ajoute rien de lui-même. BLS Data Entry Keyers, chargé (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.integrations', 'fr', 'Chaque pays pour lequel vous devez construire, compté une fois par système ERP ou de facturation, valorisé à son tarif simple ou complexe. Aucune économie d''échelle n''est modélisée au-delà des premiers pays, ce qui rend ce chiffre prudent plutôt qu''optimiste.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.lanes', 'fr', 'Combien de chantiers pays vous pouvez réellement staffer en même temps. Change la durée écoulée et le dernier début responsable ; jamais l''effort total. Suppose une capacité constante — sans courbe d''apprentissage entre les pays.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.nomandate', 'fr', 'Des pays que vous avez sélectionnés et qui ne portent aujourd''hui aucune obligation, chiffrés au tarif simple. Ils partagent la bande sans échéance fixe avec des pays où l''obligation est déjà pleinement en vigueur — mais seuls ceux-ci sont facultatifs. Les autres sont en retard.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.pace', 'fr', 'Un multiplicateur unique appliqué à chaque durée de phase. Ambitieux (×0,75) suppose une plateforme éprouvée et une équipe dédiée ; Prudent (×1,3) suppose des ressources partagées et une gouvernance normale. Un curseur de jugement, pas une référence.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.savePct', 'fr', 'Quelle part du coût par facture l''automatisation supprime, appliquée aux bases AP et AR. Valeur par défaut 60 %, le plancher de la fourchette 60–80 % de la HMRC ; les coûts de canal de l''ATO impliquent indépendamment 67–70 % (note B).');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.scope', 'fr', 'Conformité seule modélise l''obligation comme un chantier informatique, ce qu''achètent la plupart des programmes : la saisie et l''émission sont économisées, la revue et l''approbation non. Le périmètre plus large ajoute la refonte des processus, et une phase de changement à chaque chantier pays.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.vida', 'fr', 'La directive (UE) 2025/516 du Conseil rend la facturation électronique structurée et la télédéclaration obligatoires pour le B2B intracommunautaire à compter du 1er juillet 2030, liant les 27 États membres qu''ils aient légiféré ou non au niveau national. Valorisée comme COMPLEXE parce qu''elle porte une obligation déclarative.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.volAP', 'fr', 'Factures fournisseurs reçues dans l''année, pour toutes les entités du périmètre. Comptez des documents, pas des commandes ni des lignes — chaque référence ici s''entend par document. Détermine l''économie AP et la ligne des reprises.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'help.volAR', 'fr', 'Factures clients que vous émettez dans l''année. C''est là que mordent les obligations : les régimes de clearance et de déclaration encadrent ce que vous envoyez, pas ce que vous recevez. Détermine l''économie AR.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.arShare', 'fr', 'E-factures émises aujourd''hui %');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cImplC', 'fr', 'Coût par intégration COMPLEXE');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cImplS', 'fr', 'Coût par intégration SIMPLE');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cPlat.derived', 'fr', 'Approximatif : {vol} factures &times; {fee} chacune. C''est un multiplicateur grossier par facture pour la technologie &mdash; le prix réel de votre prestataire sera différent, et c''est celui-là qu''il faut saisir ici.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cPlat2', 'fr', 'Frais logiciels / an');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.cRun', 'fr', 'Coûts de fonctionnement internes par an');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.costAR', 'fr', 'Coût AR par facture');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.costNow', 'fr', 'Coût AP par facture');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.countries', 'fr', 'Pays dans le périmètre');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.countryNoMatch', 'fr', 'Aucun résultat. Videz la recherche pour voir tous les pays.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.countrySearch', 'fr', 'Rechercher parmi 70 pays');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'input.currency', 'fr', 'Devise');
