INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'score.durations', 'fr', '<strong>Et chaque date du plan de vagues repose sur une note D.</strong> Les durées de phase sont {0}, parce qu''aucun cabinet d''analystes ne publie de durées de mise en œuvre crédibles par pays &mdash; cela a été vérifié. Vous pouvez les modifier dans ce même panneau.');
