INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.emptyChart', 'fr', 'Aucun pays sélectionné n''a à la fois une échéance datée à venir et une obligation à construire : il n''y a donc pas de chronologie de déploiement à tracer. Les pays où l''obligation est déjà en vigueur demandent tout de même une remise à niveau &mdash; voir le tableau ci-dessous.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.emptyTable', 'fr', 'Aucun pays sélectionné n''a d''échéance datée à venir. Ceux où l''obligation est déjà en vigueur demandent tout de même une remise à niveau &mdash; voir la liste des obligations en vigueur ci-dessous.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.euWide', 'fr', 'La directive (UE) 2025/516 du Conseil lie chaque État membre de l''UE à compter du 1er juillet 2030, qu''il légifère ou non sur sa propre obligation nationale. {0}');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.euWide.h', 'fr', 'Obligation à l''échelle de l''UE.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.inforce', 'fr', '<strong>Déjà en vigueur, aucune autre étape datée ({0}) :</strong> {1}. Ce sont des sujets de conformité immédiate, pas des lignes de plan projet.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro', 'fr', 'Calculé à rebours depuis l''échéance publiée de chaque pays {0}, à travers des durées de phase que vous maîtrisez {1}.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro3', 'fr', 'Les achats sont modélisés une seule fois, pas par pays.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.intro4', 'fr', 'L''une de ces vagues est l''obligation européenne et non une obligation nationale ; elle couvre les {0} que vous avez sélectionnés.');
INSERT OR REPLACE INTO translations (namespace, key, lang, value) VALUES ('roi', 'waves.noMandate', 'fr', '<strong>Aucune obligation, inclus sur votre sélection ({0}) :</strong> {1}. Chiffrés au tarif simple et planifiés en une seule vague discrétionnaire &mdash; il n''y a aucune échéance à manquer, ce travail peut donc commencer dès que vous avez de la capacité.');
