-- ---- 31 benchmarks: hint and citation, label NULL --------------------
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Moyenne de marché Ardent Partners, données 2025', 'Ardent Partners, <em>The State of ePayables 2025</em>, publié le 22 janv. 2026. Coût moyen de marché par facture : 9,84 USD, sur 204 professionnels de la fonction AP. Libre d''accès et primaire.' FROM roi_benchmarks WHERE key = 'ap_cost_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Médiane APQC Open Standards Benchmarking', 'APQC Open Standards Benchmarking, indicateur &ldquo;number of invoices processed per FTE that performs the process process accounts payable&rdquo; : <strong>médiane de 12 000 par ETP et par an</strong>. Primaire, attribuable et publiquement affiché sur la page de l''indicateur ; les valeurs de quartile sont réservées aux adhérents APQC et ne sont pas utilisées ici. APQC indique par ailleurs que les meilleurs sont environ cinq fois plus productifs que les derniers : une médiane isolée masque donc une très large dispersion &mdash; elle ne sert dans ce modèle qu''à donner au volume de factures une relation défendable avec l''effectif, jamais à affirmer ce qu''une entreprise donnée devrait atteindre.' FROM roi_benchmarks WHERE key = 'ap_invoices_per_fte';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Calculé à partir des chiffres ATO/Deloitte — voir la source', 'Calculé à partir du <em>Peppol eInvoicing value assessment</em> de l''Australian Taxation Office / Deloitte Access Economics : papier 30,87 AUD, PDF 27,67 AUD, e-facture 9,18 AUD, ce que l''ATO présente explicitement comme <strong>une estimation de coût partagée entre l''émetteur et le destinataire</strong>. L''ATO publie aussi la répartition &mdash; <strong>40 % au processus clients, 60 % au processus fournisseurs</strong> &mdash; la part AR est donc l''attribution de l''ATO elle-même, pas la nôtre.<br><br><strong>Note B, et jusqu''au 16 août 2026 pour la mauvaise raison.</strong> La source indiquait auparavant que la note B tenait au fait que l''isolement d''un chiffre AR était notre propre calcul. C''est faux : l''ATO publie cette répartition, sur la même page. Les vraies raisons sont que les estimations sont australiennes, datent de 2016, ne portent aucune taille d''échantillon publiée, et que la conversion en dollars américains est de notre fait. Même note, honnêtement motivée &mdash; et la correction s''imposait, car quiconque trouvait la phrase sur la répartition aurait eu raison de promouvoir cette ligne en A au vu de l''ancienne formulation.' FROM roi_benchmarks WHERE key = 'ar_cost_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Billentis situe l''Europe à 64 % et le monde à 29 % — nous retenons le plus élevé par défaut', 'La part des factures que vous ÉMETTEZ qui partent déjà sous forme d''e-factures structurées. Ni des PDF ni des e-mails : un système de facturation qui envoie un PDF a numérisé le document et non la transaction, et l''ATO chiffre un PDF à 27,67 AUD contre 30,87 AUD pour le papier et 9,18 AUD pour une véritable e-facture.<br><br><strong>Billentis, <em>Riding the Tornado</em> (2026)</strong>, est la seule source qui mesure l''ÉMISSION plutôt que la réception &mdash; elle compte les volumes transmis au lieu de sonder les boîtes de réception. Sur environ 300 milliards de factures B2B dans le monde, quelque 87 à 88 milliards sont électroniques : <strong>29 % dans le monde, environ 64 % en Europe, environ 78 % en Amérique latine</strong>.<br><br><strong>Valeur par défaut 64 %, délibérément le chiffre le plus élevé dont nous disposons.</strong> La mesure mondiale est de 29 %, et la part côté réception d''Ardent implique 51 %. Les 64 % européens sont gonflés par les pays déjà passés au numérique &mdash; l''Italie approche 97 % et y est arrivée par obligation &mdash; ce chiffre est donc sans doute trop élevé pour un pays dont l''obligation n''est pas encore tombée, et c''est précisément ce cas que ce planificateur chiffre. Nous le retenons quand même, parce qu''un dossier de rentabilité doit se tromper à son propre détriment. <strong>Baissez-le si vous connaissez votre situation</strong> ; chaque point retiré augmente l''économie affichée.<br><br>Note B : Billentis est un organisme crédible qui mesure la bonne chose, mais les chiffres nous parviennent via les synthèses publiées du rapport et non par notre lecture de la source primaire, et le dénominateur n''est pas reproductible de façon indépendante.' FROM roi_benchmarks WHERE key = 'ar_einvoice_share_now';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'L''ATO répartit le coût partagé 60 AP / 40 AR', 'Australian Taxation Office, <em>Peppol eInvoicing value assessment</em> : les coûts par facture qu''elle publie sont <strong>une estimation de coût partagée entre l''émetteur et le destinataire</strong>, et l''ATO précise que &ldquo;for the purposes of this assessment 40% of this cost is attributed to the accounts receivable process and 60% to accounts payable&rdquo;. Conservé ici parce que deux autres chiffres de cette page en dépendent. Note B et non A : l''ATO publie la répartition sans taille d''échantillon et indique que les estimations sous-jacentes datent de 2016.' FROM roi_benchmarks WHERE key = 'ato_ap_cost_share';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'ATO / Deloitte, temps de traitement des factures d''achat', 'Australian Taxation Office / Deloitte Access Economics, <em>Peppol eInvoicing value assessment</em> : le traitement d''une facture d''achat est décomposé en réception 7 minutes, validation 2, revue 7 et approbation 5 &mdash; 21 minutes au total, dont <strong>9 minutes (43 %) de réception et de validation</strong>, soit le travail de saisie que la facturation électronique supprime. La même page indique que l''essentiel du coût du papier et du PDF &ldquo;is attributable to the manual work required to enter the invoice data into your systems&rdquo;, ce qui explique que la référence par facture ne puisse PAS être comptée EN PLUS comme une économie d''ETP. La revue et l''approbation relèvent du métier et ne sont pas supposées disparaître. L''ATO indique que ces temps datent de 2016.' FROM roi_benchmarks WHERE key = 'capture_share_of_ap';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — aucune référence crédible n''existe', 'Une valeur indicative, pas une référence. Aucun cabinet d''analystes ne publie de coûts de mise en œuvre crédibles par pays pour la facturation électronique &mdash; cela a été vérifié directement. Remplacez-la par vos propres devis avant de montrer à quiconque le délai de récupération.' FROM roi_benchmarks WHERE key = 'cost_per_integration';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — un raccordement CTC ou 5 coins', 'Estimation de praticien de Dan pour raccorder un système de facturation à un pays CTC ou 5 coins, où l''administration fiscale est partie à la transaction. Pas une référence, pour la même raison que le tarif simple. Remplacez-la par un devis de prestataire.' FROM roi_benchmarks WHERE key = 'cost_per_integration_complex';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — un raccordement 4 coins décentralisé', 'Estimation de praticien de Dan pour raccorder un système de facturation à un pays 4 coins. Pas une référence : aucun cabinet d''analystes ne publie de coûts de mise en œuvre crédibles par pays pour la facturation électronique, ce que l''audit des preuves a confirmé sur dix d''entre eux. Remplacez-la par un devis de prestataire.' FROM roi_benchmarks WHERE key = 'cost_per_integration_simple';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'HMRC 60–80 % ; les données de canal ATO impliquent 67–70 %', 'Consultation HMRC / DBT, 13 févr. 2025 : &ldquo;Industry estimates suggest that moving to e-invoicing reduces invoicing costs by 60-80%.&rdquo; <strong>La HMRC ne cite aucune étude</strong> &mdash; vérifié dans la consultation d''origine &mdash; et Ardent Partners publie la même fourchette pour <em>une automatisation AP complète comparée aux méthodes manuelles et papier</em>, ce qui est un programme plus vaste que la conformité seule.<br><br><strong>La fourchette est néanmoins étayée, par une mesure de canal indépendante.</strong> Le Peppol value assessment de l''ATO chiffre une facture papier à 30,87 AUD, un PDF à 27,67 et une e-facture à 9,18. Ces rapports impliquent une <strong>réduction de 70,3 % depuis le papier et de 66,8 % depuis le PDF</strong> &mdash; sans échelle, la devise et la répartition émetteur/destinataire ne les affectent donc pas, et ils tombent en plein dans la fourchette de la HMRC. Deux sources sans lien, deux méthodes, une réponse.<br><br><strong>Valeur par défaut 60 %, le plancher plutôt que le milieu.</strong> L''ATO justifierait 67 %. Un chiffre prudent sous une fourchette corroborée est une meilleure position que son centre, et cette donnée d''entrée vous appartient si votre point de départ est réellement le papier.' FROM roi_benchmarks WHERE key = 'cost_reduction_pct';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Ardent Partners, données 2025', 'Ardent Partners, <em>The State of ePayables 2025</em> : délai de traitement moyen du marché 8,2 jours ; Best-in-Class 2,9 jours contre 13,5 pour tous les autres. <strong>Délibérément NON présenté comme une preuve que la facturation électronique raccourcit les délais.</strong> Ardent définit Best-in-Class comme les 20 % d''entreprises ayant les coûts de traitement les plus bas et les &ldquo;shortest average invoice process times&rdquo; &mdash; le délai fait partie de la définition, l''écart de 79 % est donc une tautologie et non un résultat. Le chiffre est cité ici pour qu''il figure au dossier, et la raison de ne pas s''appuyer dessus également.' FROM roi_benchmarks WHERE key = 'cycle_time_days';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'OCDE, janv. 2026 — le mécanisme, pas l''ordre de grandeur', 'OCDE, <em>Digital Continuous Transactional Reporting for Value Added Tax</em>, 9 janv. 2026 : le DCTR &ldquo;typically requires the (near) real-time reporting of invoices or transactional data to tax authorities, most often with the objective of strengthening VAT compliance and risk management.&rdquo; Établit le mécanisme ; il s''agit d''orientations de conception et non d''une étude d''impact, elle ne soutient donc aucun pourcentage.' FROM roi_benchmarks WHERE key = 'dctr_mechanism';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'La moyenne de marché est de 51 % — c''est votre chiffre qui compte', 'La part de vos factures fournisseurs qui arrivent DÉJÀ sous forme d''e-factures structurées. Pas des PDF : un PDF doit encore être lu et saisi, et l''ATO le chiffre à 27,67 AUD contre 30,87 AUD pour le papier et 9,18 AUD pour une véritable e-facture. <strong>C''est le principal levier sur la ligne du coût de traitement</strong>, parce qu''une économie ne se prend qu''une fois &mdash; ce qui arrive déjà structuré l''a déjà encaissée. Fixé par défaut à 50 %, proche de la moyenne de marché, sur décision de Dan ; ajustez-le à votre situation, et à 0 si vous partez de zéro.' FROM roi_benchmarks WHERE key = 'einvoice_share_now';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Notre hypothèse — délibérément pas 100 %', 'Notre hypothèse, pas une référence. Les données de facture structurées suppriment l''erreur de saisie au point d''entrée, mais <strong>toute exception n''est pas une erreur de saisie</strong> &mdash; un prix contesté, une livraison incomplète ou un bon de commande manquant bloqueront toujours une facture, si proprement que les données soient arrivées, et aucun format ne règle un désaccord commercial. 80 % est une décote délibérée sur l''hypothèse que la majeure partie, mais pas la totalité, des exceptions actuelles relève de la qualité des données.<br><br><strong>Ce qu''Ardent soutient et ne soutient pas.</strong> Ardent Partners énonce le mécanisme directement &mdash; &ldquo;eInvoicing drives process efficiencies by eliminating data capture and manual data entry&rdquo; &mdash; et rapporte que 48 % des professionnels AP citent un taux d''exception élevé parmi leurs principaux défis. Mais le rapport ne contient <strong>aucune ventilation des exceptions par cause</strong> ni <strong>aucune réduction chiffrée</strong> liée à l''automatisation : il ne peut donc ni confirmer ni infirmer les 80 %. Mécanisme attesté, ordre de grandeur de notre fait : la même position probatoire que l''OCDE sur le volet indirect.<br><br>Il fixe en revanche un <strong>plafond</strong>, désormais appliqué. Voir l''enveloppe de réduction des exceptions à côté de cette ligne.' FROM roi_benchmarks WHERE key = 'error_elimination_pct';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Ardent Partners, données 2025', 'Ardent Partners, <em>The State of ePayables 2025</em> : taux d''exception moyen du marché 18,4 % ; Best-in-Class 11,1 % contre 20,9 % pour tous les autres. À noter qu''il est passé de 14 % dans l''édition précédente. <strong>Non interchangeable avec le taux d''erreur manuel de 10 % qu''utilise ce modèle</strong> : une exception est toute facture nécessitant une intervention manuelle, une erreur est plus étroite, et substituer discrètement l''un à l''autre doublerait presque une ligne du dossier de rentabilité sur un simple changement de définition.' FROM roi_benchmarks WHERE key = 'exception_rate';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Ardent Partners : Best-in-Class contre tous les autres', 'Ardent Partners, <em>The State of ePayables 2025</em> : les organisations Best-in-Class affichent un taux d''exception de <strong>11,1 %</strong> contre <strong>20,9 %</strong> pour toutes les autres &mdash; un écart de <strong>9,8 points de pourcentage</strong>. Utilisé ici comme PLAFOND et non comme objectif. C''est la totalité de l''écart observé entre le quartile le plus automatisé du marché et tous les autres, toutes causes d''exception confondues ; la facturation électronique n''est qu''un facteur parmi d''autres, puisque les Best-in-Class traitent aussi 51 % des factures de bout en bout contre 29 %, et ont 1,4&times; plus de fournisseurs raccordés. Si la revendication propre de ce modèle (taux d''erreur &times; erreurs éliminées) dépasse 9,8 points, il affirme que la facturation électronique à elle seule fait mieux que tout ce que font les Best-in-Class réunies, et la page le dit. <strong>Note B : les chiffres d''Ardent, notre soustraction.</strong> À noter également qu''Ardent ne publie aucune ventilation des exceptions par cause : rien ici n''établit donc quelle part de cet écart est imputable à la saisie.' FROM roi_benchmarks WHERE key = 'exception_reduction_pp';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — vos propres coûts de fonctionnement', 'Une valeur indicative, pas une référence. Vos propres coûts de fonctionnement sont ici la seule donnée d''entrée qui ait du sens.' FROM roi_benchmarks WHERE key = 'internal_run_cost';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Salaire médian BLS, chargé du facteur de coût employeur BLS', 'US Bureau of Labor Statistics, Occupational Employment and Wage Statistics : comptables et auditeurs, salaire annuel médian <strong>81 680 $</strong> (mai 2024). Chargé à <strong>&times;1,43</strong>, à partir des BLS Employer Costs for Employee Compensation (mars 2026), où les salaires représentent 69,9 % de la rémunération totale dans le secteur privé &mdash; le coût employeur est donc le salaire / 0,699. Soit <strong>116 800 $</strong>. Note B plutôt que A parce que les deux données d''entrée sont primaires BLS mais que <strong>la multiplication est de notre fait</strong>, la même base sur laquelle le coût AR par facture est noté B. C''est le taux de la personne qui fait la déclaration fiscale et la préparation aux contrôles, <em>pas</em> celle qui saisit les factures &mdash; ce sont des métiers différents à peu près au double du prix, et jusqu''au 14 août 2026 un seul champ valorisait les deux. Les frais généraux au-delà des charges patronales légales ne sont pas inclus ; ajoutez-les si votre propre taux chargé les porte.' FROM roi_benchmarks WHERE key = 'loaded_fte_cost';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Salaire médian BLS, chargé du facteur de coût employeur BLS', 'US Bureau of Labor Statistics, Occupational Employment and Wage Statistics : <strong>Data Entry Keyers</strong> (SOC 43-9021), salaire annuel médian <strong>37 790 $</strong> (mai 2023) ; dixième centile 28 250 $, quatre-vingt-dixième 55 330 $. Chargé à <strong>&times;1,43</strong> d''après les BLS Employer Costs for Employee Compensation (mars 2026), cela donne <strong>54 000 $</strong>. Note B : données BLS, notre multiplication. <strong>C''est un chiffre américain en interne, et la saisie est la fonction la plus délocalisée de la finance</strong> &mdash; un centre de services partagés à Cracovie, Lisbonne ou Manille sera nettement en dessous, et quiconque connaît son propre taux devrait l''utiliser. À noter aussi que le BLS projette un recul de 6 % de ce métier d''ici 2034 et l''attribue à l''automatisation des tâches comptables routinières, soit précisément l''effet que ce modèle chiffre.' FROM roi_benchmarks WHERE key = 'loaded_fte_cost_entry';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Consultation HMRC — sans source à l''intérieur', 'Même consultation HMRC / DBT : &ldquo;Manually entering supplier invoice data has an average error rate of approximately 10%.&rdquo; Aucune source n''est donnée pour ce chiffre dans le document.' FROM roi_benchmarks WHERE key = 'manual_error_rate';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Ardent Partners, données 2025', 'Ardent Partners, <em>The State of ePayables 2025</em> : <strong>51,4 %</strong> des factures sont reçues par voie électronique contre 48,6 % sur papier. Utilisé uniquement pour décomposer le coût moyen mixte de 9,84 $ en ses composantes manuelle et électronique, afin que la part propre au lecteur s''applique à la bonne base. <strong>Note B plutôt que A parce qu''Ardent ne définit pas &ldquo;electronically&rdquo;</strong> &mdash; le rapport ne donne aucune ventilation par format, il n''est donc pas établi si les PDF envoyés par e-mail sont comptés. Mesuré, ce qui relève de la note A ; publié sans dénominateur, ce qui n''en relève pas.' FROM roi_benchmarks WHERE key = 'market_einvoice_share';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Un seul NHS trust — une anecdote, pas une référence', 'Guide du UK Small Business Commissioner, page mise à jour le 16 janv. 2026 : un NHS trust a traité les e-factures en 24 heures contre 10 jours sur papier, a été payé presque deux fois plus vite et a vu les relances fournisseurs baisser d''environ 15 %. <strong>Une seule organisation, non nommée et non datée.</strong> Indicatif seulement ; jamais monétisé dans ce modèle.' FROM roi_benchmarks WHERE key = 'nhs_query_reduction';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — dépend entièrement de votre prestataire', 'Une valeur indicative, pas une référence. Les prix des prestataires sur ce marché varient d''un ordre de grandeur et sont rarement publiés.' FROM roi_benchmarks WHERE key = 'platform_cost_year';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — un multiplicateur approximatif par document', 'Une valeur indicative, pas une référence. Les prix des prestataires sur ce marché varient d''un ordre de grandeur et sont rarement publiés ; 0,40 USD par document est un ordre de grandeur arrondi pour les frais de réseau et de plateforme, pas une moyenne relevée. Le montant annuel qui en découle devrait être remplacé par le devis de votre prestataire.' FROM roi_benchmarks WHERE key = 'platform_fee_per_invoice';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'ATO / Deloitte : 15 min pour une exception de traitement', 'Australian Taxation Office, <em>Peppol eInvoicing value assessment</em>. Exceptions sur factures d''achat, avec le temps moyen attribué à la correction de chacune : <strong>paiement contesté 20 min</strong> (10 % des factures), <strong>exception de traitement 15 min</strong> (24 %), <strong>retard de paiement 5 min</strong> (48 %), <strong>exactitude des données 5 min</strong> (3,6 %). Fixé par défaut à l''exception de traitement de 15 minutes, parce que cette ligne couvre la relance, la ressaisie et la réapprobation plutôt qu''une frappe corrigée &mdash; mettez 5 si vous ne visez que la frappe, ou 20 si vos exceptions sont réellement contestées.<br><br><strong>Il s''agit d''un effort de travail, pas d''un délai écoulé.</strong> L''ATO convertit ces minutes en argent avec les données salariales de l''Australian Bureau of Statistics, ce qui n''est valable que pour du temps effectif. APQC publie des échantillons plus larges pour la résolution des exceptions &mdash; 5,0 jours ouvrés (n=461) et 4,0 jours calendaires (n=2 861) &mdash; mais les deux sont, par leur propre définition, des <em>délais écoulés</em>, et multiplier l''un ou l''autre par un taux salarial donnerait environ 1 000 $ par exception.<br><br><strong>Note B, et la raison tient à la provenance plutôt qu''à l''éditeur.</strong> L''ATO est primaire et libre d''accès, mais attribue les estimations sous-jacentes à Deloitte Access Economics et les date de 2016 ; aucune taille d''échantillon n''est publiée pour les temps eux-mêmes, et le rapport Deloitte n''est pas accessible publiquement. Mesuré ou modélisé n''est pas établi &mdash; ce qui relève de la note B et non de A.<br><br><strong>Notez que le taux voisin vient d''une autre source.</strong> Ce modèle utilise le taux d''erreur manuel de 10 % de la HMRC ; le propre taux d''exception d''exactitude des données de l''ATO est de 3,6 %. Ce ne sont pas les mêmes mesures &mdash; la HMRC compte les erreurs introduites par la saisie, l''ATO compte les exceptions levées &mdash; mais si vous voulez une méthodologie homogène de bout en bout, mettez aussi le taux d''erreur à 3,6 %.' FROM roi_benchmarks WHERE key = 'rework_minutes';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Aucune référence n''existe — notre estimation', 'Notre estimation. Aucun cabinet d''analystes ne publie de coût par exception défendable ; remplacer ceci par le vôtre vaut strictement mieux que notre supposition.' FROM roi_benchmarks WHERE key = 'rework_per_error';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Ardent Partners, données 2025', 'Ardent Partners, <em>The State of ePayables 2025</em> : les fonctions AP Best-in-Class consacrent <strong>12,8 %</strong> du temps de leurs équipes aux relances fournisseurs contre <strong>24,0 %</strong> pour toutes les autres ; la moyenne de marché pour le temps consacré aux fournisseurs dans l''ensemble est de 21,9 %. Mesuré, primaire et attribuable. <strong>Point décisif : cet indicateur ne fait pas partie de la définition Best-in-Class d''Ardent</strong> &mdash; c''est ce qui le rend utilisable là où l''écart de délai ne l''est pas. Il reste une corrélation avec une fonction AP performante dans son ensemble : Ardent n''isole pas la facturation électronique et rapporte seulement que les meilleurs ont 1,4&times; plus de fournisseurs capables de facturer électroniquement et 1,8&times; plus de traitement de bout en bout. <strong>Ne porte aucune valeur dans ce modèle.</strong>' FROM roi_benchmarks WHERE key = 'supplier_inquiry_time';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — notre hypothèse, sous forme de ratio', 'Un plafond sur le taux par pays, parce que l''ordre de grandeur est une hypothèse et qu''une hypothèse sans plafond part à la dérive : au maximum <strong>20 %</strong> de l''effort AP impliqué par votre volume est retenu, quel que soit le nombre de pays sélectionnés. Ramené de 36 % le 14 août 2026, <strong>en même temps que le taux de l''ETP fiscal passait de 62 000 $ à 116 800 $</strong>, parce que les deux se multiplient et que corriger l''un sans l''autre aggrave l''erreur au lieu de la réparer. 36 % signifiait l''essentiel d''une fonction fiscale supprimée par la seule facturation électronique, ce qui n''est pas défendable ; 20 % représentent environ 1,67 ETP sur 25 pays à clearance, soit à peu près trois semaines par an chacun de rapprochement et de préparation aux contrôles en moins. Toujours notre chiffre, toujours note D, et toujours le premier à discuter.' FROM roi_benchmarks WHERE key = 'tax_effort_cap';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'VALEUR INDICATIVE — notre hypothèse, sous forme de ratio', 'Notre hypothèse, pas une référence : chaque pays à clearance ou à déclaration au niveau de la facture est modélisé comme plaçant 1,8 % de l''effort AP impliqué par votre volume dans le périmètre d''une déclaration fiscale et d''une préparation aux contrôles allégées. Rien n''est affirmé pour ce chiffre. Il est exprimé en RATIO plutôt qu''en effectif afin d''évoluer avec la taille de l''entreprise ; à la valeur par défaut de la page de 100 000 factures AP, il équivaut exactement aux 0,15 ETP forfaitaires par pays qu''il remplace.' FROM roi_benchmarks WHERE key = 'tax_effort_per_jurisdiction';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Largement cité, non défendable sur le plan causal', 'Baisses de l''écart de TVA souvent citées pour la Hongrie (10,4 %&rarr;4,4 %), l''Italie (21,8 %&rarr;10,8 %), la Pologne (12,5 %&rarr;3,3 %) et l''Espagne (6,1 %&rarr;0,8 %), 2019&ndash;21. <strong>Deux corrections issues de la vérification :</strong> ce sont des chiffres de la Commission européenne / CASE, pas de l''OCDE ; et les analyses pays de la Commission elle-même pour la Hongrie, l''Italie et la Pologne créditent la reprise économique post-pandémie plutôt que la télédéclaration. <strong>Ne porte aucune valeur nulle part dans ce modèle.</strong>' FROM roi_benchmarks WHERE key = 'vat_gap_context';
INSERT OR REPLACE INTO roi_benchmark_translations (benchmark_id, lang, label, hint, citation)
  SELECT id, 'fr', '', 'Notre hypothèse — une construction déclarative sur une plateforme existante', 'Notre hypothèse, pas une référence. Un État membre de l''UE dont l''échéance nationale précède juillet 2030 fait face à une seconde obligation : l''exigence de télédéclaration de la directive (UE) 2025/516 du Conseil. Elle est modélisée à <strong>la moitié</strong> d''une intégration pays complète, parce qu''à cette date la plateforme, le raccordement au point d''accès et les données de référence existent déjà, et que le choix du prestataire et la contractualisation sont modélisés une fois au niveau du programme et ne se répètent pas. Ce qui est réellement nouveau, c''est l''extraction déclarative, sa transmission à l''administration fiscale et son test. Rien n''est affirmé pour ce chiffre : une seconde intégration complète facturerait deux fois une plateforme achetée une seule fois, et zéro afficherait l''échéance tout en niant le travail. Si votre construction de 2027 produit déjà une extraction déclarative conforme, baissez-le.' FROM roi_benchmarks WHERE key = 'vida_second_wave_ratio';

-- ---- 7 phases --------------------------------------------------------
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'Choix du prestataire', 'Au niveau du programme : une seule fois pour l''ensemble, pas par pays. Veille marché, appel d''offres, démonstrations et appels de référence. Dimensionné sur le pays le plus complexe du périmètre — un seul régime de clearance dans la liste signifie que vous achetez une plateforme capable de clearance.' FROM roi_phases WHERE key = 'vendor';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'Contractualisation', 'Au niveau du programme : une seule fois, pas par pays. Volet commercial, juridique, revue de sécurité, signature. La phase qui glisse le plus souvent, et elle précède chaque chantier pays — c''est pourquoi le chemin critique passe ici par les achats et non par la livraison.' FROM roi_phases WHERE key = 'contract';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'Mobilisation', 'Par pays. Équipe constituée, périmètre confirmé avec les responsables finance et fiscalité locaux, accès obtenu à l''ERP du pays. Estimation de praticien pour un déploiement sur une plateforme déjà en place — pas une mobilisation de programme ERP, plusieurs fois plus longue.' FROM roi_phases WHERE key = 'mobilise';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'Conception', 'Par pays. Traduire l''obligation locale dans vos données : correspondance des champs, lacunes des données de référence, le flux de clearance ou de déclaration, l''archivage. Évolue avec la complexité du pays et avec le nombre de systèmes qui doivent l''alimenter.' FROM roi_phases WHERE key = 'design';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'Construction', 'Par pays. Configurer et intégrer — connecteur, transformation, validation, gestion des erreurs. La plus longue phase technique et celle où se trouve le vrai travail. Évolue avec la complexité et le nombre de systèmes, exactement comme la conception.' FROM roi_phases WHERE key = 'build';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'UAT &amp; bascule', 'Par pays. Test de bout en bout avec l''administration fiscale ou le point d''accès, certification là où un pays l''exige, puis bascule vers la facturation réelle. Court, parce qu''un UAT de facturation électronique est un test d''intégration étroit — mais il dépend de délais de réponse de l''administration que vous ne maîtrisez pas.' FROM roi_phases WHERE key = 'uat';
INSERT OR REPLACE INTO roi_phase_translations (phase_id, lang, name, note)
  SELECT id, 'fr', 'Changement de processus &amp; formation', 'N''apparaît que si l''automatisation du processus AP est dans le périmètre. Refonte des processus, reformation, embarquement des fournisseurs — la phase qui rend réelles les économies directes. Plus longue que les phases techniques, et elle retombe sur le métier et non sur l''informatique, ce qui explique que la conformité seule ne les encaisse pas.' FROM roi_phases WHERE key = 'change';

